// Test-owned attachment storage; production supplies the PM Host's registered resolver.
const resolveAttachmentPath = (input: { attachmentsDir: string; attachment: ChatAttachment }) =>
  path.join(input.attachmentsDir, input.attachment.id);
const buildAntigravityPrompt = (input: Omit<Parameters<typeof buildNativeAntigravityPrompt>[0], "resolveAttachmentPath">) =>
  buildNativeAntigravityPrompt({ ...input,
    resolveAttachmentPath: attachment => resolveAttachmentPath({ attachmentsDir: input.attachmentsDir, attachment }) });
